<?php use VazinCMS\Security; ?><section class="title"><div><h1>فاکتورها</h1><p>صدور فاکتور، مانده و وضعیت وصول</p></div></section>
<?php if($error):?><div class="alert error"><?=Security::e($error)?></div><?php endif;?>
<section class="split"><div class="panel"><h2>فاکتور جدید</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><label>سفارش<select name="order_id" required><option value="">انتخاب سفارش</option><?php foreach($orders as $o):?><option value="<?=$o['id']?>"><?=Security::e($o['order_number'].' — '.$o['customer'].' — '.$o['amount'].' '.$o['currency'])?></option><?php endforeach;?></select></label><label>سررسید<input type="datetime-local" name="due_at"></label><button>صدور فاکتور</button></form></div><div class="panel"><h2>فیلتر</h2><form method="get"><label>وضعیت<select name="status"><option value="">همه</option><?php foreach(['unpaid'=>'پرداخت‌نشده','partial'=>'پرداخت ناقص','paid'=>'پرداخت‌شده','cancelled'=>'لغوشده','refunded'=>'بازپرداخت'] as $v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><button class="secondary">اعمال</button></form></div></section>
<section class="panel"><div class="table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>مبلغ</th><th>وصول‌شده</th><th>مانده</th><th>وضعیت</th><th>سررسید</th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><a href="/admin/invoices/<?=$i['id']?>"><?=Security::e($i['invoice_number'])?></a></td><td><?=Security::e($i['customer'])?></td><td><?=Security::e($i['total'].' '.$i['currency'])?></td><td><?=Security::e($i['paid_amount'].' '.$i['currency'])?></td><td><?=Security::e((string)max(0,(float)$i['total']-(float)$i['paid_amount']).' '.$i['currency'])?></td><td><span class="badge"><?=Security::e($i['status'])?></span></td><td><?=Security::e((string)$i['due_at'])?></td></tr><?php endforeach;?></tbody></table></div></section>
